  _ = `Falha ao carregar imagem`,
  _ = `Selecione o assunto principal do seu evento ou anúncio. A categoria que selecionar deve corresponder à descrição do título do seu evento e à imagem de capa.`,
  _ = `De que se trata o seu evento ou anúncio?`,
  _ = `Alterar categoria`,
  _ = `Categoria`,
  _ = `Você não pode alterar a categoria de um evento que tenha uma página especial de atualização ativada. Para alterá-la, primeiro desative a página na aba da "Página especial".`,
  _ = `Não é possível alterar a categoria de uma página de criador.`,
  _ = `Não é possível alterar a categoria de uma grande atualização associada a uma mensagem de divulgação.`,
  _ = `Atualização de jogo`,
  _ = `Informe os jogadores sobre atualizações, novos conteúdos, ajustes em recursos e correções.`,
  _ = `Convide os seus fãs para conversar, conhecer os desenvolvedores ou tirar dúvidas.`,
  _ = `Informe aos jogadores que o seu jogo já está disponível`,
  _ = `Chame os jogadores para assistir a um torneio, transmissões ao vivo de desenvolvedores ou um canal famoso que esteja exibindo o seu jogo`,
  _ = `Esta é a melhor opção para correções ou alterações que afetam só uma parte dos jogadores.`,
  _ = `Esta opção é mais apropriada para atualizações regulares de recursos que ocorrem semanalmente ou mensalmente.`,
  _ = `Use esta opção para as suas atualizações mais significativas, que geralmente ocorrem a cada trimestre ou algumas vezes no ano.`,
  _ = `Anuncie um novo conteúdo adicional à venda para o seu jogo.`,
  _ = `Informe aos jogadores a data exata do lançamento.`,
  _ = `Anuncie um desconto por tempo limitado para este jogo.`,
  _ = `Anuncie descontos em itens que possam interessar aos jogadores. Por exemplo, itens virtuais, moedas virtuais ou conteúdo adicional.`,
  _ = `Anuncie um período de tempo em que jogadores ganharão mais pontos de experiência ao jogar.`,
  _ = `Anuncie a chance de obtenção de itens raros ou exclusivos ou aumente a chance de jogadores participantes ganharem itens.`,
  _ = `Anuncie que, ao cumprir tarefas e/ou participar de eventos da comunidade, os jogadores terão acesso a bônus ou benefícios no jogo por tempo limitado.`,
  _ = `Um desafio diário, semanal, mensal ou especial.`,
  _ = `Chame os seus fãs para participar de um concurso. É um concurso de artes? Envios à Oficina Steam? Um torneio no jogo?`,
  _ = `Convide os seus fãs para se encontrarem em pessoa ou avise-os se estará participando de um evento interessante.`,
  _ = `Conte aos jogadores algo importante. Alcançou uma meta incrível? Trabalhando em algo interessante?`,
  _ = `Agende ou anuncie os detalhes sobre como participar de testes beta.`,
  _ = `Uma oferta de tempo limitado para que usuários do Steam experimentem o seu jogo, conteúdo adicional ou conteúdo no jogo. Pode ser um fim de semana gratuito ou outra forma de acesso a conteúdo por tempo limitado.`,
  _ = `Descreva o lançamento da sua temporada ou passe de batalha (um período de semanas ou meses com conteúdo especial, bônus para quem participar ou subeventos).`,
  _ = `Use esta categoria para falar sobre outro jogo que está lançando ou outra plataforma na qual seu jogo será lançado. Esta é a única categoria a ser usada se a sua publicação for sobre outro jogo, plataforma ou loja.`,
  _ = `Chame o seu público para jogar junto em uma data específica.`,
  _ = `Organize um evento especial no jogo com temática de Dia das Bruxas.`,
  _ = `Personalize a sua página de criador (página de desenvolvedor, distribuidora ou série). A página visível publicamente mais recente será exibida.`,
  _ = `Anuncie o lançamento de itens virtuais ou conteúdo disponível no jogo.`,
  _ = `Explique aos seus usuários do Steam detalhes sobre um passe de batalha ou temporada já lançado. Esta opção é mais apropriada para estabelecer a regularidade de conteúdo novo ao longo de um período de tempo.`,
  _ = `Lançamento de jogo ou conteúdo / testes beta`,
  _ = `Anuncie quando o seu jogo, beta, conteúdo adicional ou temporada especial serão lançados.`,
  _ = `Descreva o lançamento do seu conteúdo adicional, temporada ou passe de batalha. Comunique aos seus usuários o que esperar e se o conteúdo é gratuito ou pago.`,
  _ = `Eventos de transmissão podem ter uma Transmissão Steam ou site externo de transmissão associado. É possível definir o horário estimado de início e término. Transmissões Steam podem ser exibidos na página do jogo, desenvolvedor e distribuidora na loja.`,
  _ = `Selecione um tipo de transmissão ao vivo`,
  _ = `Desconto, promoção ou teste gratuito`,
  _ = `Para descontos, testes, demonstrações ou promoções do seu jogo, conteúdo adicional ou dentro do jogo. Anuncie descontos para clientes que não são compradores, ou avise quem já é.`,
  _ = `Ofertas costumam ser anunciadas só quando começam. É possível agendar um desconto aqui com o anúncio e arte promocional.`,
  _ = `Selecione um tipo de desconto.`,
  _ = `Agende um desconto para o seu jogo ou conteúdo adicional na Loja Steam.`,
  _ = `Evento no jogo`,
