  _ = `%1$s: eventos especiais`,
  _ = `Você pode usar esse tipo de evento para destacar o seu jogo de formas especiais durante este evento. Clique no botão de informações abaixo para saber mais sobre como esses eventos são usados durante "%1$s".`,
  _ = `Mais sobre tipos de eventos`,
