  _ = `Você pode criar até %1$s eventos desse tipo.`,
  _ = `Você já criou a quantidade máxima de eventos (%1$s).`,
  _ = `Outro`,
  _ = `Assim você não nos pega de surpresa.`,
  _ = `Atualização do jogo — Na maioria dos casos, o jogo será atualizado automaticamente com tudo que há de novo`,
  _ = `Lançamento — Anúncio de quando o jogo ou um conteúdo adicional será lançado`,
  _ = `Transmissão — Transmissão oficial do jogo organizada pelos desenvolvedores`,
  _ = `Oferta — Este jogo ou conteúdo adicional está em oferta!`,
  _ = `Evento no jogo — Um evento está ocorrendo no jogo durante o período, com missões especiais, benefícios e bônus para quem participar`,
  _ = `Conversa — Uma conversa onde os membros da equipe de desenvolvimento compartilharão novidades e tirarão as dúvidas dos fãs`,
  _ = `Evento em pessoa — A equipe de desenvolvimento está organizando um evento e divulgou os detalhes para quem quiser participar.`,
  _ = `Notícias — Anúncio de algo importante para a comunidade do jogo.`,
  _ = `Outro — O evento não se encaixa em nenhuma das categorias do Steam.`,
  _ = `Esta seção explicará como este evento é diferente dos demais ao passar o mouse sobre uma categoria específica.`,
  _ = `Passe o mouse sobre uma categoria para detalhes`,
  _ = `%1$s serão exibidos nos lugares de sempre, incluindo a biblioteca, página na loja e central da comunidade.`,
