  _ = `NOVIDADE: sugestão de indicação aos Prêmios Steam`,
  _ = `Convide os seus fãs para indicar o seu jogo a uma das categorias dos Prêmios Steam deste ano (categoria disponível até o fim da fase de indicações).`,
