  _ = `Eventos especiais do Steam Vem Aí`,
  _ = `Mais informações sobre o Steam Vem Aí`,
  _ = `(Opcional) É possível criar até dois eventos do seguinte tipo durante o Steam Vem Aí.`,
  _ = `Esse tipo só pode ser usado em eventos novos, não para eventos já publicados.`,
  _ = `Como membro da equipe de suporte da Valve, você pode ignorar o limite. A alteração de um evento publicado não conta para o limite, então prossiga com cuidado.`,
  _ = `Lamentamos, mas só é possível ter %1$s evento desse tipo.`,
  _ = `Lamentamos, mas só é possível ter %1$s eventos desse tipo.`,
  _ = `Entrar em contato com o suporte do desenvolvedor`,
  _ = `Como membro da equipe de suporte da Valve, você pode ignorar o limite. Para tal, você precisa configurar e publicar o evento em nome do parceiro Steamworks.`,
  _ = `Steam Vem Aí: apresentação rápida`,
  _ = `Use isto para oferecer aos usuários do Steam detalhes interessantes sobre a sua equipe de desenvolvimento, o conteúdo da sua demonstração e como ele se relaciona com o seu jogo. Se fornecidas, estas informações serão destacadas na página do seu jogo na Loja Steam e com o seu jogo nas páginas do Steam Vem Aí.`,
  _ = `Steam Vem Aí: transmissão ao Vivo`,
  _ = `Selecione a data da transmissão ao vivo do jogo para todos os fãs verem. Esse evento será automaticamente exibido no calendário oficial do Steam Vem Aí e na página do seu jogo.`,
  _ = `Steam Vem Aí: horário de atendimento`,
  _ = `Selecione quando os seus fãs poderão entrar em contato com você e a sua equipe para fazer perguntas e conversar na plataforma mais conveniente, seja na Conversa Steam, no Discord ou em uma sessão de perguntas e respostas (AMA) do Reddit.`,
