  _ = `Evento de ofertas`,
  _ = `Cria uma página de promoção de jogos na sua página de criador.`,
  _ = `Estes anúncios aparecerão na página principal do grupo e na Central de Notícias personalizada dos seus seguidores.`,
  _ = `%1$s impressões; lido %2$s vezes`,
