  _ = `Leituras: %1$s`,
  _ = `O widget de agenda de eventos permite adicionar um navegador de eventos futuros à página da promoção. Desta forma, os jogos participantes ganharão mais destaque, recompensando a interação com o público do Steam durante a promoção por meio de eventos específicos de um jogo, como transmissões ao vivo e sessões de perguntas e respostas.`,
  _ = `É preciso escolher um ou mais tipos de evento que terão permissão para aparecer na agenda.`,
  _ = `Escolha o período da agenda. O período não precisa ser igual ao do evento, caso o evento seja para anunciar uma agenda futura.`,
  _ = `Por padrão, a página da promoção exibirá uma %1$s, que será a fonte dos eventos. Ela poderá ser vista pelos administradores da promoção imediatamente e por todos quando a página estiver visível.`,
  _ = `central de notícias`,
  _ = `Há %1$s tipo de evento ativado`,
  _ = `Há %1$s tipos de evento ativados`,
  _ = `Priorizar demonstrações no widget`,
  _ = `Ao ativar esta opção, a ação de jogar demonstração terá prioridade ao exibir os detalhes do jogo e ao passar o mouse. Da mesma forma, o evento de lançamento de demonstração ficará disponível no período da agenda.`,
  _ = `Usar data de início do evento`,
  _ = `Usar data de término do evento`,
  _ = `Eventos incluídos:`,
  _ = `Permitir que todos os eventos elegíveis de aplicativos participantes apareçam na agenda.`,
  _ = `A agenda sempre exibirá qualquer evento elegível do grupo base e todos os eventos de um circuito. Assinalar esta caixa permitirá que os eventos elegíveis de qualquer aplicativo participante também apareçam na agenda. Ao desassinalar, a agenda estará limitada a eventos associados ao grupo da Comunidade Steam associado à página ou eventos explicitamente listados nos circuitos.`,
  _ = `Aviso: o horário de início na agenda é anterior ao horário de início do evento. Tem certeza de que está correto?`,
