  _ = `Editar: <1>painel da página de criador</1>`,
  _ = `Boas-vindas!`,
  _ = `<1>Seus jogos</1>: os seus jogos são exibidos na lista de aplicativos vinculados abaixo, prontos para uso. Basta adicionar e configurar seções abaixo para divulgar os seus jogos, conteúdos adicionais, demonstrações e trilhas sonoras da forma que melhor atenda às suas necessidades.`,
  _ = `<1>Vincular mais jogos</1>: caso estejam faltando jogos na lista abaixo, significa que você não os vinculou a esta página de criador. Para instruções de como fazê-lo, consulte a <2>documentação sobre páginas de desenvolvedores e distribuidoras</2>.`,
  _ = `<1>Configuração padrão</1>: você encontrará abaixo um conjunto de seções padrão já configuradas para destacar os seus produtos populares, recomendados e recém-lançados. Sinta-se à vontade para manter todas, nenhuma ou algumas delas.`,
