  _ = `Data de término do evento`,
  _ = `Eventos desta categoria costumam ter uma data de término.`,
  _ = `Selecione uma data de término para que o Steam saiba quando indicar que o evento acabou. Isso permitirá ao Steam priorizar os seus outros eventos que são mais recentes ou estão acontecendo no momento.`,
