  _ = `Terminar em um horário específico...`,
  _ = `Insira a hora no seu fuso horário local. Ela será automaticamente convertida e exibida na hora local dos jogadores.`,
  _ = `Lembretes automáticos`,
  _ = `Fãs podem escolher serem notificados do início de eventos visíveis publicamente E que se iniciem em uma data futura. O Steam enviará uma notificação automática pelo aplicativo e/ou e-mail ao usuário Steam de acordo com as preferências deste.`,
