  _ = `Manter quebras de linha`,
  _ = `Quebras de linha não costumam fazer efeito em HTML, mas em BBCode elas são exibidas como linhas em branco. Caso tenha usado marcadores <p> ou <br>, deixe a caixa desmarcada. Caso costume usar programas que adicionam marcadores <br> de forma automática para quebras de linha, você provavelmente deverá marcar esta caixa.`,
