  _ = `Pré-visualização:`,
  _ = `Este tipo de evento será automaticamente publicado no horário agendado e NÃO poderá ser publicado antes da data e hora de início.`,
  _ = `Ao publicar o evento, todas as alterações serão salvas e o evento se tornará visível de acordo com as configurações de visibilidade.`,
  _ = `Publicar como não listado`,
  _ = `Ao publicar o evento, todas as alterações serão salvas e o evento se tornará visível para quem tiver o link dele. O evento não aparecerá em listas de eventos, mas os usuários poderão vê-lo se tiverem o link.`,
  _ = `Publicar`,
  _ = `Ao publicar a página, todas as alterações serão salvas e a página de criador possivelmente se tornará visível para quem tiver o link dela. Os usuários podem conseguir vê-la se tiverem o link. Para tornar esta página a sua página de criador, você também precisará ativá-la após a publicação.`,
  _ = `Pronto para salvar as alterações e publicar o evento?`,
  _ = `O evento ficará imediatamente visível ao público.`,
  _ = `O evento permanecerá oculto até %1$s e se tornará publicamente visível desta data em diante.`,
  _ = `  O conteúdo do evento poderá ser editado após a publicação.`,
  _ = `Aviso: não é possível desfazer a publicação de um evento já publicado.`,
  _ = `Tudo pronto para salvar as alterações e publicar a página?`,
  _ = `A página não ficará visível enquanto não a tornar ativa no painel da página de criador.`,
  _ = `O conteúdo da página poderá ser editado após a publicação.`,
  _ = `(Uso interno da Valve) Como este grupo tem um mapeamento para um projeto do Crowdin, a publicação ativará o envio automático de atualizações para o Crowdin. Você pode desativar novamente quando quiser.`,
  _ = `Data de publicação personalizada`,
  _ = `A data deve ser entre agora e a data de início do evento`,
  _ = `Apenas para datas personalizadas`,
  _ = `Não é possível publicar um evento sem primeiro salvá-lo com sucesso`,
  _ = `Publicação indisponível até que seja aprovado pela Valve`,
  _ = `Use o botão à direita para enviar a sua página para aprovação com, no mínimo, sete dias de antecedência da data de publicação desejada para garantir que haja tempo necessário para análise/aprovação, e para que as alterações necessárias possam ser feitas`,
  _ = `Erro interno do editor. Não carregamos o texto traduzido, bloqueando as opções de salvar e publicar para evitar a perda de dados.`,
  _ = `Aviso: o conteúdo do evento ou anúncio foi alterado em %1$s pelo usuário %2$s. A versão que começou a editar é de %3$s. Deseja substituir tais alterações?`,
  _ = `Deseja substituir as alterações?`,
  _ = `Falha ao publicar`,
  _ = `Publicar com avisos`,
  _ = `Estado`,
  _ = `Por favor, aguarde o processamento da publicação...`,
  _ = `Ignorar avisos e continuar com publicação...`,
  _ = `Tornar visível publicamente assim que publicado`,
  _ = `Ocultar até a data de início definida acima`,
  _ = `Ocultar até...`,
  _ = `Os usuários do Steam poderão ver o evento assim que ele for publicado. Essa é a escolha padrão para anúncios ou recursos já lançados.`,
  _ = `O evento permanecerá oculto até o início do evento, momento no qual se tornará visível publicamente de forma automática.`,
  _ = `O evento permanecerá oculto até a data especificada, mesmo depois de publicado. Assim, você pode preparar vários eventos futuros, que serão divulgados automaticamente nas datas especificadas, mantendo o público informado e engajado.`,
  _ = `Oculto`,
