  _ = `O evento começará e se tornará visível publicamente em %1$s.`,
  _ = `Não é possível alterar a data de início/término de um evento já publicado.`,
  _ = `Este evento terminou em %1$s. A data e a hora de término não podem ser alteradas.`,
  _ = `O evento se tornou visível em %1$s %3$se começou em %2$s`,
