  _ = `Editar / Migrar`,
  _ = `Este anúncio foi criado numa versão anterior do sistema de anúncios, sem categorias, artes ou data de término. Para migrar o anúncio e ter acesso aos novos recursos, basta editá-lo e salvá-lo.`,
  _ = `O evento será excluído do Steam, junto com os seus metadados (avaliações, comentários, estatísticas). Caso já esteja visível, o evento redirecionará a uma página vazia e não será recomendado aos usuários. Essa ação é irreversível.`,
  _ = `Permite ver como o evento será visto por usuários do Steam, com uma barra superior para facilitar a troca de idioma.`,
