  _ = `dias`,
  _ = `semana`,
  _ = `semanas`,
  _ = `A data/hora é anterior à hora de início permitida (%1$s).`,
  _ = `A data/hora é posterior à hora de fim permitida (%1$s).`,
  _ = `O horário foi bloqueado por %1$s. Não é possível agendar um evento que comece ou termine no horário bloqueado, nem um evento que comece antes e termine após esse horário.`,
  _ = `O horário foi bloqueado por %1$s com o seguinte motivo: %2$s. Não é possível agendar um evento que comece ou termine no horário bloqueado, nem um evento que comece antes e termine após esse horário.`,
  _ = `Fuso horário`,
  _ = `Informe a data e hora no seu fuso horário local. A informação será automaticamente convertida para o horário local da pessoa que estiver visualizando.`,
  _ = `Opa, o evento não pode termina antes de começar.`,
  _ = `Data e hora de início se referem ao passado`,
  _ = `Data e hora de início antes do permitido`,
  _ = `Data e hora de início depois do permitido`,
  _ = `Data e hora de término depois do permitido`,
  _ = `Resumo`,
  _ = `(Até %1$s caracteres. Exibido em listas de eventos)`,
  _ = `(Limite de %1$s caracteres alcançado. Exibido em listas de eventos)`,
  _ = `Até %1$s caracteres, sem BBCode. Esta descrição é exibida na Biblioteca Steam. A descrição curta é opcional — caso não seja fornecida, ela será gerada automaticamente a partir do primeiro parágrafo da descrição do evento.`,
  _ = `Opcional: informe um resumo do evento de até %1$s caracteres. Deixe em branco para que seja gerado automaticamente.`,
  _ = `Resumo gerado automaticamente: `,
  _ = `%1$s caracteres restantes`,
  _ = `O título do evento, que pode conter até %1$s caracteres, sem BBCode.`,
  _ = `O título desta página para referência. É exibido apenas no seu painel.`,
  _ = `Este é o subtítulo do evento, que pode conter até %1$s caracteres (BBCode e outras formatações não estão disponíveis). O subtítulo será usado juntamente do título na página do evento ou anúncio.`,
  _ = `O resumo pode ter até %1$s caracteres de texto. O resumo aparece abaixo do título quando estiver em uma lista de eventos ou em destaque. Quando estiver em branco, o Steam automaticamente fará um resumo do conteúdo a partir do início da descrição do evento para cada idioma.`,
  _ = `Opções`,
