  _ = `Esta publicação é relevante para quem jogar a demonstração do jogo?`,
  _ = `Exibir como um evento em destaque na página de detalhes do jogo na biblioteca`,
  _ = `Antes de poder ativar a exibição no destaque, associe uma imagem de destaque em inglês na aba "%1$s"`,
  _ = `Exibir texto automático?`,
  _ = `O título e subtítulo do evento, será posicionado automaticamente no canto superior direito desta imagem, com uma sobreposição mais escura.`,
  _ = `Este evento ficará temporariamente em destaque acima da seção de atividade de cada usuário. Esta opção deve ser usada apenas para grandes eventos, com um intervalo adequado entre cada um para que não haja sempre um evento em destaque na página de detalhes do jogo.`,
  _ = `Exibir na seção "Novidades" da biblioteca`,
  _ = `A seção "Novidades" da Biblioteca Steam exibirá a sua publicação aos usuários com base no tempo de jogo e outros fatores.`,
  _ = `Exibir na página de detalhes do jogo na biblioteca`,
  _ = `Exibir na página da Loja Steam`,
  _ = `Tenha cuidado com o conteúdo que será exibido a usuários do Steam que têm o seu jogo na biblioteca ou que estejam visitando a página do produto na loja. Por exemplo, não é permitido incluir um link para comprar o seu jogo em outra loja. Siga também as %1$s.`,
  _ = `regras gerais de conteúdo do Steam`,
  _ = `Ocultar da página principal da biblioteca`,
  _ = `Tem conteúdo adulto`,
  _ = `Assinale esta opção caso a publicação contenha imagens ou outro tipo de conteúdo explícito. Disponível apenas para aplicativos marcados como "somente para adultos".`,
  _ = `Ocultar da página de detalhes do jogo na biblioteca`,
  _ = `Ocultar da página da Loja Steam`,
  _ = `Configurações de moderação (têm prioridade sobre configurações de parceiros).`,
  _ = `Editar restrição regional`,
