  _ = `O tipo de evento atual ("%1$s") não é exibido neste tipo de página.`,
  _ = `Exibir no Steam China`,
  _ = `O evento só será exibido a usuários do Steam China ao ativar esta opção`,
  _ = `Ocultar no Steam`,
  _ = `Para eventos exibidos no Steam China, esta opção pode ser usada para que o evento não seja exibido a usuários do Steam Global`,
  _ = `O evento a ser clonado possui conteúdo nos seguintes idiomas. Assinale as caixas dos idiomas que deseja manter no evento clonado.`,
  _ = `Na maioria dos casos, não é uma boa ideia clonar os idiomas existentes.`,
