  _ = `Uma imagem, cobrir e desfocar`,
  _ = `Cor das setas do carrossel`,
  _ = `Caso a cor ou a imagem de fundo seja muito clara, pode ser difícil ver as setas. Use esta configuração para alterar a cor branca padrão das setas do carrossel.`,
  _ = `Caso a cor ou a imagem de fundo seja muito clara, pode ser difícil ver as setas. Use esta configuração para alterar as cores branca e cinza padrão da trilha de navegação do carrossel. A trilha de navegação é exibida principalmente em telas menores, como a do Steam Deck.`,
  _ = `Carregando dados da demonstração`,
  _ = `Não há demonstrações lançadas para compartilhar a publicação.`,
  _ = `É necessário salvar o evento para compartilhá-lo com a sua demonstração.`,
  _ = `Quando publicado, o evento ou anúncio será exibido na página da demonstração na biblioteca. Assim, você pode se comunicar com aqueles que possuem apenas a demonstração. `,
  _ = `Eventos temáticos: %1$s`,
  _ = `Dia das Bruxas de 2022`,
  _ = `Este evento se trata de atualizações do seu jogo para o Dia das Bruxas de 2022? Caso esteja adicionando ao seu jogo novos mapas, visuais, artes ou outro tipo de conteúdo relacionado ao Dia das Bruxas, ou tenha eventos por tempo limitado com conteúdo especial, desafios ou outras atividades horripilantes similares, gostaríamos de saber mais. Estamos pensando em formas melhores de exibir eventos temáticos para um público maior, mas primeiro precisamos ter mais noção sobre que tipo de atividades os desenvolvedores estão (se estiverem) trazendo aos seus jogos para celebrar a data. Selecione abaixo caso este evento seja uma atualização para o Dia das Bruxas de 2022.`,
  _ = `Eventos do Dia das Bruxas`,
  _ = `Você está organizando um evento ou adicionando conteúdo temático de Dia das Bruxas? Consulte a %1$s para mais informações sobre como participar do Susteam com um evento temático de Dia das Bruxas no seu jogo.`,
  _ = `Documentação do Susteam — evento de Dia das Bruxas do Steam`,
  _ = `Novo conteúdo adicional ou adição ao jogo`,
  _ = `Extensões permanentes de Dia das Bruxas para o jogo`,
  _ = `Anuncie eventos de Dia das Bruxas de duração limitada no jogo oferecendo itens, bônus, recompensas, experiência etc. Eventos desse tipo têm hora de início e término.`,
  _ = `Categoria dos Prêmios Steam para indicar`,
  _ = `Selecione uma categoria específica à qual você sugere que os seus fãs indiquem o seu jogo. Com isso, eles poderão realizar a indicação diretamente do evento!`,
  _ = `A maioria das categorias dos Prêmios Steam é para jogos lançados em %1$s (isto é, desde a última edição dos Prêmios Steam, em %2$s). Como o seu jogo foi lançado antes dessa data, ele só poderá ser indicado à categoria "Feito com amor".`,
  _ = `Para mais informações e baixar os recursos gráficos dos Prêmios Steam, com modelos para uso em materiais de divulgação, consulte a nossa <1>documentação</1>.`,
  _ = `Este jogo não pode ser indicado para nenhuma categoria dos Prêmios Steam. Caso acredite que seja um erro, entre em contato com o <1>Suporte Steamworks</1>.`,
  _ = `Confirmação de página da loja não visível`,
  _ = `A página da loja para o AppID %1$s não está visível atualmente. Ao publicar este evento, os usuários tomarão conhecimento da existência do jogo. Caso escolha publicá-lo mesmo assim, você deverá confirmar que está de acordo aqui.`,
  _ = `Publicar o evento mesmo que a página da loja não esteja visível?`,
