  _ = `Cabeçalho`,
  _ = `Banner de destaque na loja`,
  _ = `Banner de destaque na loja`,
  _ = `Banner de destaque na loja (dispositivos móveis)`,
  _ = `Banner "Melhor do Ano"`,
  _ = `Banner "Melhor do Ano" para dispositivo móvel`,
