  _ = `Cápsula principal`,
  _ = `Cápsula vertical`,
  _ = `Fundo de promoção cruzada`,
  _ = `Fundo de promoção cruzada`,
  _ = `Imagem exibida como fundo das seções de promoção cruzada desta promoção, como a da página de descontos e eventos. É usada uma imagem para todos os idiomas. Ela preenche toda a seção e é recortada para se ajustar ao espaço, então não coloque nada importante nas extremidades, especialmente nas extremidades superior e inferior.`,
  _ = `pelo menos %1$s px de largura x %2$s px de altura`,
  _ = `Remover fundo`,
  _ = `Nenhum fundo enviado.`,
  _ = `Escolha a posição do logotipo em relação aos jogos quando a seção for exibida em computadores. Em celulares, o logotipo sempre é exibido acima dos jogos.`,
  _ = `Disposição em computadores:`,
  _ = `Logotipo à esquerda`,
  _ = `Logotipo acima`,
  _ = `Logotipo`,
  _ = `Escolha uma cor de gradiente abaixo. Ela será exibida atrás dos jogos na seção.`,
  _ = `Cor do gradiente:`,
  _ = `Preto`,
  _ = `Escolher cor...`,
  _ = `Pré-visualizar disposições`,
  _ = `Exibir o logotipo da promoção apenas em seções de promoção cruzada`,
  _ = `Não exibir o logotipo na página promocional e na loja de pontos. Outras páginas que promovem esta promoção ainda o exibirão.`,
  _ = `Esta página promocional não exibe o seu logotipo. Ele será exibido apenas quando ela for promovida em outras páginas.`,
  _ = `Cápsulas da loja`,
  _ = `Estas cápsulas permitem que a loja destaque esta página promocional em lugares que normalmente destacam jogos: o carrossel "Destaques e recomendados", as centrais da loja e o carrinho. Elas são as mesmas cápsulas enviadas para um jogo na aba "Recursos gráficos" da página na loja, e usam o mesmo tamanho.`,
  _ = `Vocêr pode enviar todas de uma vez. Uma imagem é associada automaticamente a uma cápsula quando as suas dimensões forem idênticas à da cápsula — se houver diferença, você precisará fazer a associação manualmente e então recortá-la. Ao colocar o nome em inglês do idioma no final do nome do arquivo (ex.: "main_capsule_brazilian.jpg" para PT-BR), a imagem será automaticamente categorizada como desse idioma.`,
  _ = `Foque na marca da promoção. Certifique-se de que o logotipo esteja legível.`,
  _ = `Exibida nas seções de recomendação e nos espaços de destaque mais estreitos distribuídos pela loja.`,
  _ = `Estas imagens são pequenas, portanto, o logotipo precisa permanecer legível no menor tamanho.`,
  _ = `Usada nas listas distribuídas por toda a loja e no carrinho.`,
  _ = `Projetada para divulgar a promoção. Não inclua citações, pontuações nem prêmios.`,
  _ = `Exibida no carrossel "Destaques e recomendados", que fica na parte superior da página inicial.`,
  _ = `Uma imagem em formato vertical projetada para divulgar a promoção. Não inclua citações, pontuações nem prêmios.`,
  _ = `Pode ser exibida na parte superior da página inicial durante promoções sazonais e em outras páginas promocionais.`,
  _ = `Imagem de paisagem da biblioteca`,
