  _ = `Permite clicar no logotipo da página da promoção para encaminhar o usuário a outro lugar na loja (como a página inicial).`,
  _ = `Informe apenas a parte do endereço que vem depois do URL da página inicial da loja, sem a barra no começo. Por exemplo, informe "category/pins_pegs", sem aspas, para encaminhar para "https://store.steampowered.com/category/pins_pegs".`,
  _ = `O URL deve ser relativo ao URL da página inicial da loja, portanto, remova o prefixo "https://store.steampowered.com/". Por exemplo, informe "category/pins_pegs", sem aspas, em vez de "https://store.steampowered.com/category/pins_pegs".`,
  _ = `Remova a barra no começo. Por exemplo, digite "category/pins_pegs", sem aspas, em vez de "/category/pins_pegs".`,
  _ = `Este campo não pode conter espaços. Por exemplo, digite "category/pins_pegs", sem aspas.`,
