  _ = `A sua conta é limitada. Contas limitadas não podem salvar conteúdos de eventos. Para mais informações, consulte https://help.steampowered.com/faqs/view/71D3-35C2-AD96-AA3A.`,
  _ = `Seção marcada como oculta. Exibindo prévia para edição do grupo de imagens de fundo.`,
