  _ = `Seção marcada como oculta por não estar na lista de países permitidos. Exibindo prévia para edição do grupo de imagens de fundo.`,
  _ = `Seção marcada como oculta porque o usuário não tem o pacote. Exibindo prévia para edição do grupo de imagens de fundo.`,
  _ = `Seção marcada como oculta porque o usuário não usou um hardware específico. Exibindo prévia para edição do grupo de imagens de fundo.`,
