  _ = `CSV (valores separados por vírgulas)`,
  _ = `XML (linguagem de marcação extensível)`,
  _ = `Cria e baixa um arquivo CSV com os campos para todos os idiomas disponíveis no Steam, assim como qualquer texto previamente adicionado.`,
  _ = `Observação: ao importar o arquivo, é possível excluir qualquer idioma que você não queira alterar na importação.`,
  _ = `Selecione o formato preferido para o arquivo CSV:`,
  _ = `A opção a seguir baixará um arquivo XML por idioma que possua algum conteúdo associado. O arquivo do idioma inglês é sempre exportado.`,
  _ = `Aviso: caso o evento esteja traduzido em vários idiomas, o navegador pode alertar você de que estamos tentando baixar muitos arquivos. Permita o download, porque cada idioma é salvo em um arquivo XML diferente.`,
