  _ = `Importar CSV de localização`,
  _ = `Importar...`,
  _ = `Selecione um ou mais arquivos para importar textos traduzidos para o título, subtítulo, resumo e para a descrição. Usamos a extensão do arquivo para determinar se é uma importação XML ou CSV. Para XML, usamos o código do idioma na API no final do nome do arquivo, antes da extensão, para determinar o idioma do conteúdo do arquivo. Comece exportando o arquivo CSV ou XML para garantir o uso do formato correto.`,
  _ = `Importação de localização concluída. Os seguintes idiomas foram atualizados: %1$s`,
  _ = `Importação de localização concluída. Nenhuma alteração foi efetuada.`,
  _ = `Não foi possível processar ou reconhecer o arquivo CSV.`,
  _ = `Arquivo não possui extensão ".xml" ou ".csv"; falha ao processar o nome do arquivo: %1$s`,
  _ = `O nome do arquivo não especifica o nome do idioma na API. O nome do arquivo deve seguir o formato <nome de usuário>_<idioma>.xml: %1$s`,
  _ = `Ocorreu um erro ao processar e aplicar os dados do XML: %1$s`,
  _ = `Exportar rascunho em inglês para o Crowdin ou importar todos os outros idiomas do Crowdin`,
  _ = `Exportar para o Crowdin`,
  _ = `Deseja enviar o rascunho atual em inglês para o Crowdin e sobrescrever quaisquer strings atuais em inglês lá?`,
  _ = `Importar`,
  _ = `Deseja importar do Crowdin as strings traduzidas nos idiomas abaixo? Esta ação sobrescreverá quaisquer rascunhos locais.`,
  _ = `A página promocional foi analisada pela Valve. A partir de agora, as seguintes restrições foram aplicadas:`,
  _ = `Não é mais possível editar o URL personalizado da página promocional.`,
  _ = `Como o URL personalizado pode ser referenciado em destaques, alterá-lo faria com que o link deixasse de funcionar.`,
  _ = `Não é mais possível adicionar outros aplicativos, pacotes ou conjuntos à página promocional.`,
  _ = `A análise da página promocional abrangeu os aplicativos, pacotes e conjuntos inclusos, portanto, não é possível adicionar mais. Contudo, eles ainda podem ser movidos, reordenados e removidos.`,
  _ = `Não é possível alterar mais a página promocional.`,
  _ = `(Uso interno da Valve) Enviar atualizações automaticamente para o Crowdin`,
  _ = `Ainda não enviado para o Crowdin`,
  _ = `Ative esta opção para que as alterações no evento, quando salvas, sejam enviadas para o Crowdin para tradução. Mantenha desativada até que o texto do evento esteja estável e pronto para tradução. Caso planeje realizar muitas edições no futuro, desative, edite e, então, reative.`,
