  _ = `O evento não pode ser publicado devido aos erros abaixo. Por favor, corrija-os antes de tentar novamente.`,
  _ = `A data e hora de início do evento não foram definidas.`,
  _ = `A data e hora de início (%1$s) se referem ao passado. Ajuste-as para agora ou para o futuro. Caso permitíssemos eventos no passado, eles poderiam passar despercebidos para usuários que acessaram a sua página recentemente, já que a teriam acessado depois da data de início do evento.`,
  _ = `Data e hora de início do evento (%1$s) antes do permitido. O evento pode ter início a partir de %2$s.`,
  _ = `O evento termina antes de começar`,
  _ = `Data e hora de término não informadas: A data e hora de término são obrigatórias para este evento.`,
  _ = `A data e hora de visibilidade do evento estão para depois do início do evento, impedindo que se torne visível quando começar.`,
  _ = `A descrição não pode ultrapassar 32 mil caracteres. A descrição em %1$s ultrapassa esse limite.`,
  _ = `O evento tem um título em %1$s, mas não tem uma descrição associada a ele. Cada idioma precisa ter os dois.`,
  _ = `O evento tem uma descrição em %1$s, mas não tem um título associado a ele. Cada idioma precisa ter ou os dois.`,
