  _ = `Este evento está configurado para ser exibido no Steam China, mas falta incluir título e descrição no idioma %1$s`,
  _ = `Eventos de categoria "Grande atualização" só podem ser publicados depois de adicionar, pelo menos, a arte principal em inglês. O evento será exibido com destaque na tela de detalhes do jogo na biblioteca do cliente Steam.`,
