  _ = `Uma página de promoção só pode ter uma única seção de abas`,
  _ = `A página da loja deste jogo não está visível atualmente. Você precisa confirmar que está de acordo na aba "Opções" antes de continuar.`,
  _ = `Faltam %2$s de %3$s campos obrigatórios na aba %1$s.`,
  _ = `Os seguintes avisos podem ser ignorados e não impedem o evento de ser publicado, mas aconselhamos segui-los.`,
  _ = `O evento não possui um título e/ou uma descrição em inglês. Muitos usuários do Steam usam o inglês como idioma secundário. Sem ele, a visibilidade do evento para usuários do Steam ficará bastante limitada.`,
  _ = `Evento sem arte. Eventos podem ter artes personalizadas, ajudando a ilustrá-los e a chamar a atenção de usuários. Eventos sem artes usarão uma imagem de cápsula do jogo.`,
  _ = `Evento sem arte. Eventos podem ter artes personalizadas, ajudando a ilustrá-los e a chamar a atenção de usuários. Eventos sem artes usarão o avatar do grupo.`,
  _ = `A categoria do evento é "Outro", o que reduzirá a sua visibilidade. O Steam usa as categorias para direcionar os eventos aos usuários. O Steam considera eventos de categoria "Outro" como de menos impacto, fazendo com que sejam exibidos a menos usuários.`,
  _ = `O subtítulo foi traduzido em %1$s de %2$s idiomas. Aconselhamos que o subtítulo seja traduzido para todos os idiomas.`,
  _ = `Artes localizadas definidas para %1$s de %2$s idiomas. Não há problema caso a arte não precise de localização. Caso um idioma não tenha uma versão específica de uma arte, a versão em inglês será exibida.`,
  _ = `A data de visibilidade definida já passou e, portanto, ao salvar o evento, ele se tornará visível imediatamente, impedindo a alteração da data de início ou que o evento seja ocultado novamente.`,
  _ = `Há imagens de destaque na loja enviadas para o evento, mas ele não está marcado como destacado. Essa marcação deve ser feita pela Valve para que o banner seja exibido na página da loja.`,
  _ = `O URL-alvo do logotipo da página promocional definido não é relativo à página inicial da loja, então clicar nele direcionará os usuários a uma página com erro. O URL-alvo correto deve ser algo como "category/pins_pegs", sem aspas, não "https://store.steampowered.com/category/pins_pegs".`,
