  _ = `Selecionar arquivo`,
  _ = `Exibir distribuidoras-alvo`,
  _ = `É opcional filtrar por uma lista de distribuidoras ou AppIDs. Caso estes filtros não sejam ativados, compararemos as configurações às das demais distribuidoras no Steamworks`,
  _ = `* Exibindo %1$s`,
  _ = `Você está vendo a pré-visualização em %1$s pois o evento não possui descrição traduzida em %2$s.`,
  _ = `Resumo da visibilidade`,
  _ = `Segundo as configurações, o evento ou anúncio será exibido nos seguintes locais`,
  _ = `Locais padrão`,
  _ = `Locais opcionais`,
  _ = `Impressões`,
  _ = `Loja: na página do jogo na loja`,
  _ = `O evento será exibido na seção de notícias e eventos da página do jogo na loja.`,
  _ = `Aqui o número reflete uma estimativa da quantidade de visitantes à sua página na loja enquanto o evento aparecer.`,
  _ = `Loja: na página de jogos recém-atualizados`,
  _ = `Caso esteja usando uma rodada de visibilidade de atualização, o evento será exibido na página "Recém-atualizados" para jogadores que possuem o jogo ou o adicionaram à lista de desejos.`,
  _ = `Aqui o número representa a quantidade de usuários que têm o seu jogo ou o colocaram na lista de desejos e podem vê-lo na página de "Recém-atualizados".`,
  _ = `Notícias: na página de notícias do jogo`,
  _ = `O evento será exibido na lista de notícias, acessada ao clicar no botão "Leia notícias relacionadas" na página do jogo na loja.`,
  _ = `O número é uma estimativa da quantidade de tráfego na página de notícias do seu jogo.`,
  _ = `Comunidade: na central da comunidade do jogo`,
  _ = `Inclui a página principal e a aba de notícias da central, assim como a seção de anúncios da página na loja.`,
  _ = `Comunidade: no feed de atividades de jogadores que seguem o jogo`,
  _ = `O evento pode ser exibido no feed de atividade de jogadores que seguem o jogo.`,
  _ = `O número exibido é a quantidade de jogadores que seguem o seu jogo.`,
  _ = `No futuro:`,
  _ = `Biblioteca: na página inicial da Biblioteca Steam (possivelmente)`,
  _ = `Seus jogadores podem ver este evento no topo da tela inicial da biblioteca, dependendo da quantidade de jogos que um jogador possui e da prioridade relativa de cada anúncio ou atualização.`,
  _ = `(pendente de moderação)`,
  _ = `Biblioteca: no destaque da tela do jogo na biblioteca`,
  _ = `Se você fornecer uma imagem de banner de destaque, seu evento/anúncio pode aparecer abaixo do botão de "jogar"da tela de detalhes do seu jogo na Biblioteca Steam.`,
  _ = `Biblioteca: na tela de detalhes do jogo na Biblioteca Steam dos jogadores`,
  _ = `Seu evento vai aparecer na seção de atividade da tela do seu jogo na Biblioteca Steam do seu jogador.`,
  _ = `De acordo com a quantidade de jogadores que possuem o jogo e podem vê-lo na Biblioteca Steam.`,
  _ = `Na página da Oficina`,
  _ = `Você também pode publicar este evento/anúncio na Oficina Steam do seu jogo. Para ativar este recurso, vá para a aba de "opções" e selecione "Publicar na oficina também". Por padrão, eventos e anúncios de jogos não aparecem na oficina.`,
  _ = `Banner da promoção nas páginas de produtos do Steam`,
  _ = `Banner nas páginas de produtos visível de %1$s até %2$s`,
  _ = `É possível fornecer um banner da promoção na aba "Ofertas". Este banner será exibido na parte superior da página dos jogos em oferta e levará os usuários à página da promoção. Desta forma, usuários que souberem de um desconto em um jogo específico por meio de um e-mail da lista de desejos ou ao explorar a loja também saberão da promoção como um todo. O banner fica visível durante todo o evento ou por duas semanas, o que for mais curto. A duração do evento é determinada na aba "Opções".`,
  _ = `Notificação: e-mail para seguidores do jogo, do desenvolvedor ou da distribuidora`,
  _ = `Inclui todos os seguidores das páginas de desenvolvedores, distribuidoras e séries relacionadas ao jogo.`,
  _ = `Os seguintes desenvolvedores, distribuidoras e/ou séries não possuem links que levam a uma página pública de criador. Crie uma para que usuários possam conhecer os seus produtos, eventos e lançamentos futuros: %1$s`,
  _ = `Novidade: calendário de eventos do jogador`,
  _ = `Este evento será exibido na central de notícias de jogadores que possuem o seu jogo em suas bibliotecas, lista de desejos ou que seguem o seu jogo.`,
  _ = `Notificação: notificações push em dispositivos móveis para jogadores que as ativaram`,
  _ = `A quantidade de jogadores que escolheram receber um lembrete deste este evento (exportaram para um calendário externo ou seguiram o evento).`,
  _ = `jogadores que receberão um e-mail`,
  _ = `Quantidade estimada de e-mails com detalhes do evento. Mandamos periodicamente uma lista de e-mails relevantes para usuários que escolheram receber tal tipo de comunicação.`,
  _ = `jogadores que receberão mensagem de divulgação`,
  _ = `Quantidade estimada de jogadores que verão este evento na mensagem de divulgação personalizada dentro do cliente Steam — uma janela pop-up exibida ao iniciar o cliente Steam com promoções relevantes e informações sobre eventos interessantes.`,
  _ = `jogadores que ignoraram este evento`,
  _ = `A quantidade de jogadores que escolheram ignorar este evento.`,
  _ = `Erro ao carregar o evento`,
  _ = `Consultar documentação`,
  _ = `Análise da mensagem de divulgação de grande atualização`,
  _ = `Assim que o evento estiver pronto e não forem necessárias mais alterações, envie-o para análise de uso em uma mensagem de divulgação. Você pode publicar o evento da grande atualização quando desejar. Aguarde até %1$s dias úteis para análise e aprovação.`,
  _ = `Abra o seguinte chamado para iniciar o processo de análise.`,
  _ = `Abrir chamado de análise`,
  _ = `Chamado aberto. Revise e atualize os dados <1>aqui</1>.`,
  _ = `resumo`,
  _ = `Início da visibilidade`,
  _ = `O evento se tornará visível na maioria dos lugares depois de publicado.`,
  _ = `Esteja ciente de que novas publicações são analisadas pela nossa equipe de moderadores em ordem de publicação. Pode haver um atraso de uma ou mais horas até que notícias ou eventos apareçam na Biblioteca Steam. Quaisquer edições em uma publicação existente a colocará no fim da fila de moderação.`,
  _ = `Ou substitua o conteúdo de um evento existente`,
  _ = `Esta ação, incomumente usada, permite que você prepare atualizações em um tipo de evento de "rascunho" e depois substitua o conteúdo de um evento já publicado pelo conteúdo deste evento. Este evento desaparecerá e o respectivo conteúdo substituirá o evento-alvo publicado. A substituição não altera o tipo de evento nem as configurações de visibilidade do evento-alvo.`,
  _ = `Este evento foi clonado de: "%1$s"`,
  _ = `Substituir no evento original`,
  _ = `O conteúdo do evento que foi duplicado para gerar este evento será substituído pelo conteúdo deste evento.`,
  _ = `Aviso: o evento original deve estar publicado e visível. Não podemos substituí-lo até que esteja visível publicamente.`,
  _ = `Esta ação é imediata. O conteúdo do evento-alvo será substituído e ficará imediatamente visível publicamente no Steam. O evento atual será eliminado.`,
