  _ = `Lista de transmissores permitidos`,
  _ = `As transmissões do jogo feitas por estes usuários podem aparecer na página do evento e da loja durante o evento.`,
  _ = `Vídeo de abertura da transmissão`,
  _ = `Em desuso: o pipeline de VOD está desativado, mas não removido caso seja necessário usar vídeos antigos. Este vídeo será exibido no reprodutor de vídeo antes da programação normal. VOD deve ter permissões públicas (separadas do estado de lançamento).`,
