  _ = `Usar reprodutores mais largos`,
  _ = `Ative para remover as colunas laterais do reprodutor. Útil somente quando há apenas uma transmissão no evento e as colunas distraem o espectador da experiência.`,
  _ = `Ativar reprodutor largo`,
  _ = `Ative para exibir o botão de exibir/ocultar conversa. Com a conversa aberta, o reprodutor voltará ao modo normal (não largo). Ao ocultá-la, ele voltará ao modo largo.`,
  _ = `Permitir exibir/ocultar a conversa`,
