  _ = `Informe o ID do sorteio`,
  _ = `Caso haja um sorteio associado à transmissão que anuncia os vencedores pela conversa, então definir o ID do sorteio permitirá que as mensagens da conversa sejam obtidas mesmo com ela fechada, buscando os anúncios para o propósito exclusivo de exibi-las.`,
  _ = `Título da transmissão`,
  _ = `Selecione a partir de uma lista um título padronizado para exibição acima da transmissão na sua página na loja ou informe o seu próprio título.`,
