  _ = `Arte da transmissão`,
  _ = `Opções de arte da transmissão`,
  _ = `Exibir banners nas laterais em vez de usar a imagem de cápsula do jogo.`,
  _ = `Ative para exibir o banner na Loja Steam no lugar das imagens de cápsula do jogo. Útil quando o banner fala mais sobre o evento do que as imagens de cápsula do aplicativo ou quando a transmissão engloba mais de um jogo e você deseja usar só uma imagem para o evento.`,
  _ = `Lista de transmissores permitidos`,
