  _ = `Erro ao carregar os dados do usuário`,
  _ = `Configuração opcional que permite associar uma transmissão a um idioma específico para os espectadores. Útil para quando houver transmissões do evento em idiomas diferentes. Desta forma, podemos escolher a melhor transmissão padrão para o usuário de acordo com o idioma dele.`,
  _ = `Prioridade`,
  _ = `Defina a prioridade que essa transmissão terá em relação a outras transmissões. Transmissões de prioridade alta serão selecionadas em vez daquelas de prioridade baixa. Caso várias transmissões tenham a mesma prioridade, uma será selecionada aleatoriamente como padrão.`,
