  _ = `Enviar comentários`,
  _ = `Denunciar item`,
  _ = `Descreva por que este item viola os Termos de Serviço do Steam e inclua todo e qualquer dado ou link relevante. Não é possível retirar esta denúncia no futuro.`,
  _ = `Agenda`,
  _ = `Ferramenta de agendamento`,
  _ = `Criar uma agenda/cronograma para aparecer na sua página de eventos?`,
  _ = `Adicionar entrada na agenda`,
  _ = `Remover esta entrada`,
  _ = `Prévia do agendamento incorporado`,
  _ = `Legenda de tipo de entrada na agenda`,
  _ = `Tipo`,
  _ = `Propósito`,
  _ = `Partida competitiva`,
  _ = `Esta é uma partida competitiva entre duas ou mais pessoas/equipes. Após o fim da partida, você poderá atualizar os resultados e incluir dados sobre o vencedor.`,
  _ = `Transmissão`,
  _ = `Isto chama os usuários para assistirem a uma transmissão ao vivo no Steam ou em outro lugar durante este período.`,
  _ = `Jogar`,
  _ = `Isto pede aos usuários para participarem do evento ao iniciar o jogo e participar dele`,
  _ = `Na vida real`,
  _ = `Usado quando a parte do agendamento ocorre. Acessível apenas para participantes no local do evento e não pode ser transmitido ao vivo. Observação: pode ser melhor não incluir isto no agendamento já que os seus fãs no Steam não podem participar.`,
  _ = `Horário de início`,
  _ = `Especificado em minutos desde o início do evento`,
  _ = `Minutos`,
  _ = `Esta entrada da agenda é uma alteração das configurações padrão. Tem certeza de que quer excluir? Esta ação não poderá ser desfeita.`,
  _ = `Circuitos atuais`,
  _ = `Um circuito define um conjunto de eventos relacionados sob uma mesma imagem e esquema de cores. Um evento não precisa fazer parte de um circuito para aparecer na agenda. Exemplos de circuitos: "Palco principal" e "Circuito de artes".`,
  _ = `Nenhum circuito definido.`,
  _ = `Adicionar circuito`,
  _ = `Adiciona um novo circuito para agrupar e categorizar eventos na agenda.`,
  _ = `Excluir circuito`,
  _ = `Tem certeza de que deseja excluir este circuito?`,
  _ = `Circuito %1$s sem nome`,
  _ = `Adicionar eventos especificamente para esse circuito. Os eventos são válidos apenas se forem publicados, começarem e terminarem durante o circuito e forem do tipo de evento permitido para a agenda.`,
  _ = `Termos para eventos promocionais`,
  _ = `Antes de usar a ferramenta de edição de promoção, você deverá aceitar os requisitos abaixo.`,
  _ = `Eu estou ciente de que a página promocional deverá descrever explicitamente o grupo ou os indivíduos responsáveis pela organização da promoção ou do evento.`,
  _ = `Eu estou ciente de que não posso garantir aos participantes um nível específico de visibilidade no Steam nem cobrar pelo posicionamento na página.`,
  _ = `Eu estou ciente de que a Valve reserva-se o direito de modificar uma página promocional, o que inclui, mas não está limitado a visibilidade de jogos ou transmissões na página e textos ou imagens descritivas do evento.`,
  _ = `Eu estou ciente de que a Valve é quem decide quais eventos promover na Loja Steam e, portanto, o meu evento pode não ser promovido.`,
  _ = `Eu estou ciente de que posso adicionar à página promocional apenas os jogos que tenho permissão do desenvolvedor ou distribuidora. Os desenvolvedores dos jogos poderão vê-los como parte da promoção assim que eu adicioná-los à minha página por aqui.`,
  _ = `Aceito as regras estipuladas na %1$s.`,
  _ = `Consulte a %1$s para mais detalhes de como projetar e criar uma página promocional.`,
  _ = `documentação`,
  _ = `Contato principal`,
  _ = `Se um desenvolvedor, distribuidora ou membro da imprensa tiver alguma dúvida sobre o evento, com quem devem entrar em contato?`,
  _ = `nome do contato`,
