  _ = `Promoções regionais`,
  _ = `Promoções temáticas`,
  _ = `As diretrizes foram revisadas e aceitas.`,
  _ = `(Obrigatório) Informe o nome e o URL do organizador do evento. Esses dados serão exibidos na parte superior da página promocional. Você pode editá-los a qualquer momento.`,
  _ = `Organizadores do evento`,
  _ = `Atualizar organizadores do evento`,
  _ = `Informar dados do organizador`,
  _ = `Informe o nome da entidade responsável pela organização do evento. Você pode informar o URL da página de criador no Steam ou um URL externo. É obrigatório informar o nome em inglês e há a opção de informar a versão em outros idiomas.`,
  _ = `Esses dados serão exibidos na página promocional da seguinte forma:`,
  _ = `Adicionar organizador`,
  _ = `Nome do organizador`,
  _ = `URL`,
  _ = `Grupo de imagens traduzidas`,
  _ = `Imagem principal para grupo de imagens traduzidas`,
  _ = `Esta é a imagem padrão alternativa se não houver uma versão localizada para o idioma que o usuário estiver tentando visualizar. Pode ser uma versão sem texto ou um idioma comum para os clientes.`,
  _ = `Caso a sua imagem contenha textos, você pode enviar aqui as versões traduzidas em idiomas disponíveis no Steam. O Steam exibirá automaticamente a imagem traduzida apropriada para o usuário.`,
