  _ = `Falha de verificação: Dimensões inválidas para a arte principal do evento.

Largura mínima: %1$spx (imagem inserida: %2$spx).
Altura redimensionada mínima: %3$spx (imagem inserida: %4$spx). Redimensionamos a imagem para que tenha %5$spx de largura.`,
