  _ = `(Opcional) URL da imagem da insígnia fantasma`,
  _ = `Recursos opcionais que, se definidos, serão exibidos ao usuário ANTES de adquirir a insígnia. Isto é útil quando você deseja ocultar detalhes específicos da insígnia antes de obtê-la. O recurso deve medir 160x160 px.`,
