  _ = `Etiquetas personalizadas`,
  _ = `Permite a edição direta dos itens vinculados à promoção, assim como a importação e exportação apenas da coleção personalizada de etiquetas usadas nos itens da promoção. Esta opção é usada principalmente para importar uma seleção de etiquetas personalizadas gerenciada por uma planilha externa sem modificar as outras etiquetas dos itens. Além disso, é possível importar um subconjunto por aqui. Itens não listados não serão removidos.`,
