  _ = `Sem permissão`,
  _ = `O item não pode ser adicionado porque não está associado à página de criador (desenvolvedor, distribuidora ou série) desta página promocional. Associe o item e recarregue a página promocional para atualizar a associação.`,
  _ = `Conjunto não permitido`,
  _ = `O conjunto não pode ser adicionado porque não está associado à página de criador (desenvolvedor, distribuidora ou série) desta página promocional. Associe o item e recarregue a página promocional para atualizar a associação. Estes aplicativos não estão vinculados ao criador: (%1$s).`,
  _ = `Pacote não permitido`,
  _ = `O pacote não pode ser adicionado porque não está associado à página de criador (desenvolvedor, distribuidora ou série) desta página promocional. Associe o item e recarregue a página promocional para atualizar a associação. Estes aplicativos não estão vinculados ao criador: (%1$s).`,
  _ = `Este evento é um clone de um evento passado. O recurso da página promocional precisa ser ativado pela Valve antes que a página possa ser configurada.`,
  _ = `Promoção cruzada de página promocional`,
  _ = `Informar GID do evento promocional`,
  _ = `Este é o identificador no final do URL da página de edição de eventos. Use apenas o GID de página promocional. Consulte a documentação caso tenha dúvidas sobre como prosseguir.`,
  _ = `https://steamcommunity.com/groups/<nome do grupo>/partnerevents/edit/<COPIAR ESTE GID>`,
  _ = `O GID informado é inválido. O GID deve conter apenas algarismos.`,
  _ = `A Página promocional foi associada.`,
  _ = `O evento existe, mas não é possível associá-lo no momento. O recurso de página promocional não foi ativado ou nenhum jogo foi adicionado, portanto, não há ID interno para associar. Peça para que os organizadores configurem a página promocional e então tente associar o evento novamente.`,
  _ = `Carregando os dados da página promocional`,
  _ = `A página promocional ainda não foi publicada ou não está visível.`,
  _ = `Título da página promocional: %1$s`,
  _ = `O evento associado a esta página promocional não tem uma imagem de cápsula.`,
  _ = `Seleção de aplicativos`,
  _ = `Priorizar adições à lista de desejos`,
  _ = `Caso a página promocional referenciada contenha majoritariamente jogos não lançados, então eles provavelmente não terão dados de receita. Neste caso, é recomendável priorizar pela quantidade de adições à lista de desejos.`,
  _ = `Priorizar receita`,
  _ = `Opção padrão. Usa os dados de tendência de receita para priorizar quais jogos da página promocional referenciada exibir.`,
  _ = `Com mais de uma página promocional, a seção se transforma em um carrossel com um painel por página promocional, seguindo esta ordem. Arraste para reordenar.`,
  _ = `Adicionar outra página promocional`,
