  _ = `por nome`,
  _ = `pela qtd. de correspondências`,
  _ = `manualmente`,
  _ = `Nome deste valor de faceta. Um valor de faceta é uma opção na qual o usuário pode clicar para filtrar os jogos exibidos nesta seção. Por exemplo, "Primeira pessoa".`,
  _ = `Texto opcional a ser exibido à direita do valor da faceta. Use-o para fornecer uma breve explicação do valor da faceta. Por exemplo, "1–2 horas" para facetas que podem ser usadas em jogos com tempo de jogo curto.`,
  _ = `O nome desta faceta. Uma faceta é um grupo de opções relacionadas nas quais o usuário pode clicar para filtrar os jogos exibidos nesta seção. Por exemplo, "Gênero".`,
  _ = `Preencher automaticamente as facetas e os valores de facetas segundo categorias de marcadores da loja, como "Gênero" e "Estilo visual e ponto de vista". Após a geração automática, é possível editar manualmente cada faceta e valor de faceta conforme necessário.`,
  _ = `Remover valores de faceta não associados a qualquer um dos itens desta seção.`,
  _ = `Qual é o mínimo de resultados desejado para as facetas selecionadas? Ocultaremos todos os termos do menu à esquerda abaixo desse valor. A quantidade é calculada considerando os filtros da aba. 5 é um bom número.`,
  _ = `Exibir, no máximo, esta quantidade de opções sob qualquer categoria primária no menu à esquerda. Por exemplo, não exibir mais do que esta quantidade de gêneros em uma faceta de nome "Gênero". 5 é um bom número.`,
  _ = `Para cada faceta, ordenar os valores de faceta por esta métrica. A melhor opção é "pela qtd. de correspondências".`,
  _ = `Para cada faceta, ordenar os valores de faceta alfabeticamente.`,
  _ = `Em cada faceta, ordenar decrescentemente os valores de faceta pela quantidade de itens correspondentes. Por exemplo, em uma faceta de nome "Gênero", "RPG" aparecerá antes de "Estratégia" se houver mais RPGs nesta seção do que jogos de Estratégia.`,
  _ = `Não usar uma métrica para ordenar os valores de faceta. Eles serão exibidos na ordem definida nas listas abaixo.`,
  _ = `Cor da faceta selecionada`,
  _ = `Cor do cabeçalho`,
  _ = `Ativado por padrão`,
  _ = `Sinc. 20 primeiros marcadores da loja`,
  _ = `Por padrão, apenas os 10 primeiros marcadores da loja de cada produto são sincronizados. Assinale esta caixa para sincronizar os 20 primeiros marcadores.`,
  _ = `Gerar dados para depuração`,
  _ = `Operador lógico AND`,
  _ = `Se marcado, quando o usuário seleciona vários valores nessa faceta, o operador lógico AND dos filtros dos valores de faceta selecionados será aplicado. Caso contrário, será aplicado o operador lógico OR.`,
