  _ = `Em vez de especificar uma lista de aplicativos vinculados, você pode especificar o nome de uma central de conteúdo da qual extrair itens para esta seção. Caso o faça, a lista de aplicativos vinculados da promoção é ignorada, e a seção exibirá todo o conteúdo daquela central.`,
