  _ = `Ver loja de itens do aplicativo`,
  _ = `Adicionar item virtual`,
  _ = `Você pode escolher enviar uma arte para usar como imagem do item virtual nesta página. Caso nenhuma arte seja enviada, usaremos a imagem do item virtual na loja de itens.`,
  _ = `Resgate de item gratuito`,
  _ = `Uma seção que permite ao usuário resgatar um item gratuito. Ela será exibida quando o próximo item puder ser resgatado (se houver algum). Pode ser usada para a distribuição diária de itens. Associada ao widget de recompensas para configurar o resgate de itens da promoção.`,
