  _ = `Exibe os conteúdos adicionais disponíveis para todos os aplicativos na biblioteca do usuário. Esta seção cobre todo o catálogo do Steam, portanto, não está limitada aos itens explicitamente listados na página promocional ou na lista de itens vinculados.`,
