  _ = `Selecione um ou mais arquivos para importar textos traduzidos para o título e para o conteúdo. Usamos a extensão do arquivo para determinar se é uma importação XML ou CSV. Para XML, usamos o código do idioma na API ao final do nome do arquivo, antes da extensão, para determinar o idioma do conteúdo do arquivo. Comece exportando o arquivo CSV ou XML para garantir o uso do formato correto.`,
